mapper.sql:
WHERE user_id = #{userId}
    AND deleted = FALSE

    AND POSITION(#{filter} IN title) > 0

mapper.update:
UPDATE resume
SET title = #{title},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
    AND user_id = #{userId}
    AND deleted = FALSE

UPDATE resume
SET deleted = TRUE,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
    AND user_id = #{userId}
    AND deleted = FALSE
